from html.parser import HTMLParser
import sys
VOID={'meta','link','br','img','hr','input','rect','path','line','circle','polygon','polyline','ellipse','use'}
class P(HTMLParser):
    def __init__(s):
        super().__init__(); s.stack=[]; s.err=[]; s.secs=[]; s.tables=0
    def handle_starttag(s,t,a):
        a=dict(a)
        if t=='table': s.tables+=1
        if t=='section' and 'part' in (a.get('class') or ''):
            s.secs.append({'id':a.get('id'),'h2':False,'src':False,'depth':len(s.stack)+1})
        if s.secs and s.secs[-1].get('open',True):
            d=len(s.stack)-s.secs[-1]['depth']
            if d==0 and t=='h2': s.secs[-1]['h2']=True
            if d==0 and t=='div' and 'sources' in (a.get('class') or ''): s.secs[-1]['src']=True
        if t not in VOID: s.stack.append(t)
    def handle_startendtag(s,t,a): pass
    def handle_endtag(s,t):
        if t in VOID: return
        if not s.stack or s.stack[-1]!=t: s.err.append((s.getpos(),t,s.stack[-3:])); 
        else:
            s.stack.pop()
            if t=='section' and s.secs: s.secs[-1]['open']=False
for f in sys.argv[1:]:
    p=P(); p.feed(open(f,encoding='utf-8').read()); p.close()
